SELECT window_days AS days, concat('as of ', date_format(snapshot_at, 'MMM d, yyyy HH:mm'), ' UTC, list price') AS as_of FROM databricks_audit_dashboard.snapshot_info

SET QUERY_TAGS['cost_center'] = 'lakehouse_health';
SET QUERY_TAGS['domain'] = 'lakehouse_health';
SET QUERY_TAGS['dashboard'] = 'lakehouse_health_07_waste_savings';
