SELECT DISTINCT name AS workspace_name FROM databricks_audit_dashboard.dim_workspace WHERE name IS NOT NULL ORDER BY 1

SET QUERY_TAGS['cost_center'] = 'lakehouse_health';
SET QUERY_TAGS['domain'] = 'lakehouse_health';
SET QUERY_TAGS['dashboard'] = 'lakehouse_health_07_waste_savings';
SET QUERY_TAGS['tab'] = 'priced';
SELECT lbl_warehouse AS warehouse, ROUND(MAX(avg_read_io_cache_percent), 0) AS pct
FROM (SELECT t.*, COALESCE(COALESCE(t.`warehouse_name`, d_warehouse.n), CAST(t.`warehouse_id` AS STRING)) AS nm_warehouse, COALESCE(concat(COALESCE(t.`warehouse_name`, d_warehouse.n), ' (', CAST(t.`warehouse_id` AS STRING), ')'), CAST(t.`warehouse_id` AS STRING)) AS n_warehouse, COALESCE(d_wn.n, d_wv.workspace_id) AS ws_name, CASE WHEN COALESCE(d_wn.n, d_wv.workspace_id) IS NULL THEN COALESCE(COALESCE(t.`warehouse_name`, d_warehouse.n), CAST(t.`warehouse_id` AS STRING)) ELSE concat(COALESCE(COALESCE(t.`warehouse_name`, d_warehouse.n), CAST(t.`warehouse_id` AS STRING)), ' · ', COALESCE(d_wn.n, d_wv.workspace_id)) END AS lbl_warehouse FROM databricks_audit_dashboard.compute_warehouse_cache_reuse t LEFT JOIN (SELECT CAST(warehouse_id AS STRING) AS warehouse_id, max(warehouse_name) AS n FROM databricks_audit_dashboard.dim_warehouse GROUP BY CAST(warehouse_id AS STRING)) d_warehouse ON d_warehouse.warehouse_id = CAST(t.`warehouse_id` AS STRING) LEFT JOIN (SELECT CAST(warehouse_id AS STRING) AS k, max(workspace_id) AS workspace_id FROM databricks_audit_dashboard.dim_warehouse GROUP BY 1) d_wv ON d_wv.k = CAST(t.`warehouse_id` AS STRING) LEFT JOIN (SELECT workspace_id, max(name) AS n FROM databricks_audit_dashboard.dim_workspace GROUP BY 1) d_wn ON d_wn.workspace_id = d_wv.workspace_id)
WHERE (array_contains(:workspace, COALESCE(ws_name, '')) OR array_contains(:workspace, 'all')) AND avg_read_io_cache_percent IS NOT NULL
GROUP BY 1 ORDER BY 2 ASC LIMIT 8

SET QUERY_TAGS['cost_center'] = 'lakehouse_health';
SET QUERY_TAGS['domain'] = 'lakehouse_health';
SET QUERY_TAGS['dashboard'] = 'lakehouse_health_07_waste_savings';
SET QUERY_TAGS['tab'] = 'priced';
SELECT nm_job AS job, ROUND(SUM(est_wasted_usd_list) * (1.0 - 0.0), 0) AS usd
FROM (SELECT t.*, COALESCE(d_workspace.n, CAST(t.`workspace_id` AS STRING)) AS nm_workspace, COALESCE(concat(d_workspace.n, ' (', CAST(t.`workspace_id` AS STRING), ')'), CAST(t.`workspace_id` AS STRING)) AS n_workspace, COALESCE(d_job.n, CAST(t.`job_id` AS STRING)) AS nm_job, COALESCE(concat(d_job.n, ' (', CAST(t.`job_id` AS STRING), ')'), CAST(t.`job_id` AS STRING)) AS n_job, COALESCE(d_workspace.n, CAST(t.`workspace_id` AS STRING)) AS ws_name, CASE WHEN COALESCE(d_workspace.n, CAST(t.`workspace_id` AS STRING)) IS NULL THEN COALESCE(d_job.n, CAST(t.`job_id` AS STRING)) ELSE concat(COALESCE(d_job.n, CAST(t.`job_id` AS STRING)), ' · ', COALESCE(d_workspace.n, CAST(t.`workspace_id` AS STRING))) END AS lbl_job FROM databricks_audit_dashboard.lakeflow_failed_jobs_wasted_dbus t LEFT JOIN (SELECT CAST(workspace_id AS STRING) AS workspace_id, max(name) AS n FROM databricks_audit_dashboard.dim_workspace GROUP BY CAST(workspace_id AS STRING)) d_workspace ON d_workspace.workspace_id = CAST(t.`workspace_id` AS STRING) LEFT JOIN (SELECT CAST(workspace_id AS STRING) AS workspace_id, CAST(job_id AS STRING) AS job_id, max(name) AS n FROM databricks_audit_dashboard.dim_job GROUP BY CAST(workspace_id AS STRING), CAST(job_id AS STRING)) d_job ON d_job.workspace_id = CAST(t.`workspace_id` AS STRING) AND d_job.job_id = CAST(t.`job_id` AS STRING))
WHERE (array_contains(:workspace, COALESCE(ws_name, '')) OR array_contains(:workspace, 'all')) AND status IN ('CRITICAL', 'WARN')
GROUP BY 1 ORDER BY 2 DESC LIMIT 8

SET QUERY_TAGS['cost_center'] = 'lakehouse_health';
SET QUERY_TAGS['domain'] = 'lakehouse_health';
SET QUERY_TAGS['dashboard'] = 'lakehouse_health_07_waste_savings';
SET QUERY_TAGS['tab'] = 'flagged_not_priced';
SELECT ROUND(COALESCE(SUM(net_usage_quantity), 0), 0) AS value,
       'How much spend sits on premium-priced serverless/Photon SKUs -- worth checking it is intentional.' AS target
FROM (SELECT t.*, COALESCE(d_workspace.n, CAST(t.`workspace_id` AS STRING)) AS nm_workspace, COALESCE(concat(d_workspace.n, ' (', CAST(t.`workspace_id` AS STRING), ')'), CAST(t.`workspace_id` AS STRING)) AS n_workspace, COALESCE(d_workspace.n, CAST(t.`workspace_id` AS STRING)) AS ws_name FROM databricks_audit_dashboard.cost_premium_serverless_photon t LEFT JOIN (SELECT CAST(workspace_id AS STRING) AS workspace_id, max(name) AS n FROM databricks_audit_dashboard.dim_workspace GROUP BY CAST(workspace_id AS STRING)) d_workspace ON d_workspace.workspace_id = CAST(t.`workspace_id` AS STRING))
WHERE (array_contains(:workspace, COALESCE(ws_name, '')) OR array_contains(:workspace, 'all')) AND (COALESCE(is_serverless, FALSE) OR COALESCE(is_photon, FALSE))

